// Background sounds: public domain recordings (sounds/<id>.mp3, looped with a crossfade) with sounds generated by the Web Audio API as fallback.
export const SOUND_GROUPS = [
  { id: 'noise', ids: ['white', 'pink', 'brown', 'blue', 'violet'] },
  { id: 'nature', ids: ['rain', 'rainwindow', 'storm', 'waves', 'stream', 'fountain', 'wind', 'birds', 'forest', 'dawn', 'crickets'] },
  { id: 'ambient', ids: ['cafe', 'keyboard', 'tick'] },
  { id: 'music', ids: ['elevator', 'piano', 'satie', 'satie2', 'gymnopedie', 'debussy'] },
  { id: 'binaural', ids: ['delta', 'theta', 'alpha', 'beta'] },
];

// Ids that have a recording in sounds/ and the crossfade (seconds) used to loop it.
const RECORDED = {
  rain: 3, rainwindow: 3, storm: 3, wind: 3, birds: 3, forest: 3, dawn: 3, fountain: 3,
  cafe: 3, keyboard: 3, tick: 0.03, piano: 3, satie: 3, satie2: 3, gymnopedie: 3, debussy: 3,
};
let ctx = null, master = null, current = null;
const cache = {}, buffers = {};

function ensure() {
  if (!ctx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return false;
    ctx = new AC();
    master = ctx.createGain();
    master.connect(ctx.destination);
  }
  if (ctx.state === 'suspended') ctx.resume();
  return true;
}
function noiseBuffer(kind) {
  if (cache[kind]) return cache[kind];
  const len = Math.floor(ctx.sampleRate * 6), buf = ctx.createBuffer(1, len, ctx.sampleRate), d = buf.getChannelData(0);
  let i, w;
  if (kind === 'white') {
    for (i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
  } else if (kind === 'pink') {
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
    for (i = 0; i < len; i++) {
      w = Math.random() * 2 - 1;
      b0 = 0.99886 * b0 + w * 0.0555179; b1 = 0.99332 * b1 + w * 0.0750759; b2 = 0.969 * b2 + w * 0.153852;
      b3 = 0.8665 * b3 + w * 0.3104856; b4 = 0.55 * b4 + w * 0.5329522; b5 = -0.7616 * b5 - w * 0.016898;
      d[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362) * 0.11; b6 = w * 0.115926;
    }
  } else {
    let last = 0;
    for (i = 0; i < len; i++) { w = Math.random() * 2 - 1; last = (last + 0.02 * w) / 1.02; d[i] = last * 3.5; }
  }
  cache[kind] = buf;
  return buf;
}
function loop(kind, h) {
  const s = ctx.createBufferSource();
  s.buffer = noiseBuffer(kind); s.loop = true; s.start();
  h.nodes.push(s);
  return s;
}
function filter(type, freq, q) {
  const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = freq; if (q) f.Q.value = q; return f;
}
function gain(v) { const g = ctx.createGain(); g.gain.value = v; return g; }
function midi(n) { return 440 * Math.pow(2, (n - 69) / 12); }
function tone(type, freq, t, dur, peak, attack, dest) {
  const o = ctx.createOscillator(), g = ctx.createGain();
  o.type = type; o.frequency.value = freq;
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(peak, t + attack);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(dest);
  o.start(t); o.stop(t + dur + 0.05);
}
function burst(bus, t, freq, q, dur, amp) {
  const s = ctx.createBufferSource(), bp = filter('bandpass', freq, q), g = ctx.createGain();
  s.buffer = noiseBuffer('white');
  g.gain.setValueAtTime(amp, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  s.connect(bp); bp.connect(g); g.connect(bus);
  s.start(t, Math.random() * 5, dur + 0.02);
}
function binaural(beat) {
  return (bus, h) => {
    [[200, -1], [200 + beat, 1]].forEach((p) => {
      const o = ctx.createOscillator(), g = gain(0.12);
      o.type = 'sine'; o.frequency.value = p[0];
      if (ctx.createStereoPanner) { const pan = ctx.createStereoPanner(); pan.pan.value = p[1]; o.connect(g); g.connect(pan); pan.connect(bus); }
      else { o.connect(g); g.connect(bus); }
      o.start(); h.nodes.push(o);
    });
  };
}

const CURVE_N = 64, FADE_IN = new Float32Array(CURVE_N), FADE_OUT = new Float32Array(CURVE_N);
for (let i = 0; i < CURVE_N; i++) { FADE_IN[i] = Math.sin((i / (CURVE_N - 1)) * Math.PI / 2); FADE_OUT[i] = Math.cos((i / (CURVE_N - 1)) * Math.PI / 2); }
// Fetch and decode sounds/<id>.mp3 once; a failure is not cached so a later play can retry.
// Decoded audio is large (the piano tracks take about 50 MB each), so only the two most recent sounds stay in memory.
const MAX_DECODED = 2;
const recent = [];
function remember(id) {
  const i = recent.indexOf(id);
  if (i >= 0) recent.splice(i, 1);
  recent.push(id);
  while (recent.length > MAX_DECODED) delete buffers[recent.shift()];
}
function loadBuffer(id) {
  remember(id);
  if (!buffers[id]) {
    buffers[id] = fetch('sounds/' + id + '.mp3')
      .then((r) => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.arrayBuffer(); })
      .then((data) => new Promise((resolve, reject) => { ctx.decodeAudioData(data, resolve, reject); }));
    buffers[id].catch(() => { delete buffers[id]; });
  }
  return buffers[id];
}
// Plays the buffer as a loop: each pass overlaps the next one by `fade` seconds with an equal-power crossfade.
const LOOKAHEAD = 8; // seconds: next pass is scheduled this far ahead so a throttled timer still lands before the boundary
function startLoop(buf, fade, bus, h) {
  const dur = buf.duration, x = Math.min(fade, dur / 4);
  const pass = (t, first) => {
    const s = ctx.createBufferSource(), g = ctx.createGain();
    s.buffer = buf;
    s.connect(g); g.connect(bus);
    if (first) g.gain.setValueAtTime(1, t);
    else { g.gain.setValueAtTime(0, t); g.gain.setValueCurveAtTime(FADE_IN, t, x); }
    g.gain.setValueCurveAtTime(FADE_OUT, t + dur - x, x);
    s.start(t);
    h.nodes.push(s);
    s.onended = () => { const i = h.nodes.indexOf(s); if (i >= 0) h.nodes.splice(i, 1); try { g.disconnect(); } catch (e) { /* ignore */ } };
  };
  const next = (t) => {
    if (h.stopped) return;
    pass(t, t === h.firstStart);
    const nextT = t + dur - x;
    h.timeout = setTimeout(() => next(nextT), Math.max(250, (nextT - ctx.currentTime - LOOKAHEAD) * 1000));
  };
  h.firstStart = ctx.currentTime + 0.05;
  next(h.firstStart);
}
const BUILDERS = {
  white: (bus, h) => { loop('white', h).connect(gain(0.22)).connect(bus); },
  pink: (bus, h) => { loop('pink', h).connect(gain(0.6)).connect(bus); },
  brown: (bus, h) => { loop('brown', h).connect(gain(0.6)).connect(bus); },
  blue: (bus, h) => { loop('white', h).connect(filter('highpass', 2500)).connect(gain(0.22)).connect(bus); },
  violet: (bus, h) => { loop('white', h).connect(filter('highpass', 6000)).connect(gain(0.2)).connect(bus); },
  rain: (bus, h) => { loop('white', h).connect(filter('highpass', 900)).connect(filter('lowpass', 7000)).connect(gain(0.25)).connect(bus); },
  waves: (bus, h) => {
    const lp = filter('lowpass', 800, 0.7), swell = gain(0.5);
    loop('pink', h).connect(lp).connect(swell).connect(bus);
    [[0.09, 0.35], [0.14, 0.12]].forEach((p) => {
      const o = ctx.createOscillator(), g = gain(p[1]);
      o.frequency.value = p[0]; o.connect(g); g.connect(swell.gain); o.start(); h.nodes.push(o);
    });
    const o2 = ctx.createOscillator(), g2 = gain(450);
    o2.frequency.value = 0.09; o2.connect(g2); g2.connect(lp.frequency); o2.start(); h.nodes.push(o2);
  },
  elevator: (bus, h) => {
    const out = filter('lowpass', 2200), echo = ctx.createDelay(1), fb = gain(0.3), outGain = gain(0.7);
    echo.delayTime.value = 0.3;
    out.connect(outGain); out.connect(echo); echo.connect(fb); fb.connect(echo); echo.connect(outGain); outGain.connect(bus);
    const CHORDS = [[48, 52, 55, 59], [45, 52, 55, 60], [50, 53, 57, 60], [43, 50, 53, 59], [41, 48, 52, 57], [43, 50, 53, 59]];
    const SCALE = [60, 62, 64, 67, 69, 72, 74];
    const BAR = 3.2, STEP = 0.4;
    let barT = ctx.currentTime + 0.1, noteT = barT, bar = 0;
    const sched = () => {
      if (h.stopped) return;
      const until = ctx.currentTime + 1.5;
      while (barT < until) {
        const c = CHORDS[bar % CHORDS.length];
        c.forEach((n) => tone('triangle', midi(n), barT, BAR + 0.4, 0.05, 0.3, out));
        tone('sine', midi(c[0] - 12), barT, 1.4, 0.12, 0.05, out);
        barT += BAR; bar++;
      }
      while (noteT < until) {
        if (Math.random() < 0.65) tone('sine', midi(SCALE[Math.floor(Math.random() * SCALE.length)]), noteT, 1.1, 0.07, 0.02, out);
        noteT += STEP;
      }
    };
    sched();
    h.interval = setInterval(sched, 300);
  },
  storm: (bus, h) => {
    BUILDERS.rain(bus, h);
    const thunder = () => {
      if (h.stopped) return;
      const t = ctx.currentTime, dur = 3 + Math.random() * 3;
      const s = ctx.createBufferSource(), lp = filter('lowpass', 120 + Math.random() * 100), g = ctx.createGain();
      s.buffer = noiseBuffer('brown');
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.9, t + 0.3 + Math.random() * 0.6);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      s.connect(lp); lp.connect(g); g.connect(bus);
      s.start(t, Math.random() * 2, dur + 0.1);
      h.timeout = setTimeout(thunder, 7000 + Math.random() * 16000);
    };
    h.timeout = setTimeout(thunder, 2500);
  },
  stream: (bus, h) => {
    loop('white', h).connect(filter('bandpass', 1800, 0.5)).connect(gain(0.2)).connect(bus);
    loop('pink', h).connect(filter('lowpass', 500)).connect(gain(0.25)).connect(bus);
    const bubble = () => {
      if (h.stopped) return;
      const t = ctx.currentTime, f = 500 + Math.random() * 1200, d = 0.03 + Math.random() * 0.05;
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine'; o.frequency.setValueAtTime(f, t); o.frequency.exponentialRampToValueAtTime(f * 1.8, t + d);
      g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.05 + Math.random() * 0.06, t + 0.005);
      g.gain.exponentialRampToValueAtTime(0.0001, t + d);
      o.connect(g); g.connect(bus); o.start(t); o.stop(t + d + 0.02);
      h.timeout = setTimeout(bubble, 15 + Math.random() * 90);
    };
    bubble();
  },
  wind: (bus, h) => {
    const bp = filter('bandpass', 500, 0.8), g = gain(0.5);
    loop('pink', h).connect(bp).connect(g).connect(bus);
    [[0.07, 300, bp.frequency], [0.11, 0.25, g.gain]].forEach((p) => {
      const o = ctx.createOscillator(), d = gain(p[1]);
      o.frequency.value = p[0]; o.connect(d); d.connect(p[2]); o.start(); h.nodes.push(o);
    });
  },
  birds: (bus, h) => {
    loop('pink', h).connect(filter('lowpass', 600)).connect(gain(0.05)).connect(bus);
    const chirp = () => {
      if (h.stopped) return;
      let t = ctx.currentTime + 0.05;
      const base = 2200 + Math.random() * 2800, notes = 2 + Math.floor(Math.random() * 4);
      let dest = bus;
      if (ctx.createStereoPanner) { const pan = ctx.createStereoPanner(); pan.pan.value = Math.random() * 2 - 1; pan.connect(bus); dest = pan; }
      for (let i = 0; i < notes; i++) {
        const d = 0.06 + Math.random() * 0.08, f0 = base * (1 + Math.random() * 0.3), f1 = f0 * (Math.random() < 0.5 ? 0.7 : 1.4);
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'sine'; o.frequency.setValueAtTime(f0, t); o.frequency.exponentialRampToValueAtTime(f1, t + d);
        g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.12, t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + d);
        o.connect(g); g.connect(dest); o.start(t); o.stop(t + d + 0.02);
        t += d + 0.04 + Math.random() * 0.05;
      }
      h.timeout = setTimeout(chirp, 600 + Math.random() * 3800);
    };
    chirp();
  },
  crickets: (bus, h) => {
    [[4300, 27, 2.1], [4700, 31, 1.7]].forEach((c) => {
      const carrier = ctx.createOscillator(), a = gain(0.5), b = gain(0.5), out = gain(0.04);
      carrier.frequency.value = c[0];
      const fast = ctx.createOscillator(), fastD = gain(0.5), slow = ctx.createOscillator(), slowD = gain(0.5);
      fast.frequency.value = c[1]; slow.type = 'square'; slow.frequency.value = c[2];
      fast.connect(fastD); fastD.connect(a.gain); slow.connect(slowD); slowD.connect(b.gain);
      carrier.connect(a); a.connect(b); b.connect(out); out.connect(bus);
      [carrier, fast, slow].forEach((n) => { n.start(); h.nodes.push(n); });
    });
    loop('pink', h).connect(filter('lowpass', 400)).connect(gain(0.04)).connect(bus);
  },
  cafe: (bus, h) => {
    [[300, 0.35, 0.13], [700, 0.28, 0.19], [1300, 0.18, 0.23]].forEach((b) => {
      const bp = filter('bandpass', b[0], 0.7), g = gain(b[1]), o = ctx.createOscillator(), d = gain(b[1] * 0.6);
      loop('pink', h).connect(bp).connect(g).connect(bus);
      o.frequency.value = b[2]; o.connect(d); d.connect(g.gain); o.start(); h.nodes.push(o);
    });
    const clink = () => {
      if (h.stopped) return;
      const t = ctx.currentTime, f = 2500 + Math.random() * 2500;
      tone('sine', f, t, 0.25, 0.03 + Math.random() * 0.03, 0.002, bus);
      tone('sine', f * 1.5, t, 0.15, 0.015, 0.002, bus);
      h.timeout = setTimeout(clink, 3000 + Math.random() * 7000);
    };
    h.timeout = setTimeout(clink, 2000);
  },
  keyboard: (bus, h) => {
    const key = () => {
      if (h.stopped) return;
      burst(bus, ctx.currentTime, 2500 + Math.random() * 2500, 2, 0.03, 0.25 + Math.random() * 0.25);
      const gap = Math.random() < 0.12 ? 700 + Math.random() * 900 : 70 + Math.random() * 220;
      h.timeout = setTimeout(key, gap);
    };
    key();
  },
  tick: (bus, h) => {
    let odd = false;
    const tk = () => {
      if (h.stopped) return;
      odd = !odd;
      burst(bus, ctx.currentTime, odd ? 1800 : 1400, 4, 0.04, 0.5);
      h.interval = null;
      h.timeout = setTimeout(tk, 1000);
    };
    tk();
  },
  piano: (bus, h) => {
    const out = gain(0.8), echo = ctx.createDelay(1), fb = gain(0.35);
    echo.delayTime.value = 0.42;
    out.connect(bus); out.connect(echo); echo.connect(fb); fb.connect(echo); echo.connect(bus);
    const SCALE = [57, 60, 62, 64, 67, 69, 72, 74, 76];
    let last = 4;
    const note = () => {
      if (h.stopped) return;
      const t = ctx.currentTime + 0.02;
      last = Math.max(0, Math.min(SCALE.length - 1, last + Math.floor(Math.random() * 5) - 2));
      const f = midi(SCALE[last]);
      tone('triangle', f, t, 3.2, 0.1, 0.01, out);
      tone('sine', f * 2, t, 1.6, 0.03, 0.01, out);
      if (Math.random() < 0.25) tone('triangle', midi(SCALE[last] - 12), t, 3.5, 0.06, 0.02, out);
      h.timeout = setTimeout(note, 900 + Math.random() * 2200);
    };
    note();
  },
  // Fallbacks for ids that only exist as recordings.
  rainwindow: (bus, h) => BUILDERS.rain(bus, h),
  forest: (bus, h) => BUILDERS.birds(bus, h),
  dawn: (bus, h) => BUILDERS.birds(bus, h),
  fountain: (bus, h) => BUILDERS.stream(bus, h),
  satie: (bus, h) => BUILDERS.piano(bus, h),
  satie2: (bus, h) => BUILDERS.piano(bus, h),
  gymnopedie: (bus, h) => BUILDERS.piano(bus, h),
  debussy: (bus, h) => BUILDERS.piano(bus, h),
  delta: binaural(2), theta: binaural(6), alpha: binaural(10), beta: binaural(18),
};

export const Sound = {
  has(id) { return !!BUILDERS[id]; },
  stop() {
    const h = current;
    if (!h) return;
    current = null; h.stopped = true;
    clearTimeout(h.timeout); clearInterval(h.interval);
    const t = ctx.currentTime;
    h.bus.gain.cancelScheduledValues(t);
    h.bus.gain.setValueAtTime(h.bus.gain.value, t);
    h.bus.gain.linearRampToValueAtTime(0, t + 0.25);
    setTimeout(() => {
      h.nodes.forEach((n) => { try { n.stop(); } catch (e) { /* already stopped */ } });
      try { h.bus.disconnect(); } catch (e) { /* ignore */ }
    }, 350);
  },
  play(id) {
    if (!BUILDERS[id] || !ensure()) return;
    if (current && current.id === id) return;
    Sound.stop();
    const bus = ctx.createGain();
    bus.gain.setValueAtTime(0, ctx.currentTime);
    bus.gain.linearRampToValueAtTime(1, ctx.currentTime + 0.4);
    bus.connect(master);
    const h = { id, bus, nodes: [], stopped: false };
    current = h;
    if (!(id in RECORDED) || typeof fetch !== 'function') { BUILDERS[id](bus, h); return; }
    loadBuffer(id).then((b) => b, () => null).then((buf) => {
      if (h.stopped) return;
      if (buf) startLoop(buf, RECORDED[id], bus, h); else BUILDERS[id](bus, h);
    });
  },
  setVolume(v) { if (ensure()) master.gain.value = Math.pow(v / 100, 2); },
  playing() { return current ? current.id : null; },
  ding() {
    if (!ensure()) return;
    const t = ctx.currentTime;
    [880, 1318.5].forEach((f, i) => tone('sine', f, t + i * 0.18, 1.1, 0.25, 0.01, ctx.destination));
  },
};
